function openCategory(category){
 const addButtonLabel=currentLanguage==="ar"?"أضف إلى السلة":currentLanguage==="en"?"Add to cart":"Ajouter au panier";
 const addButton=document.querySelector("#addToOrder"); if(addButton){addButton.innerHTML=`${addButtonLabel} <span>＋</span>`;}
 state.activeCategory=category;state.selectedItem=menuItems.find(x=>x.category===category);state.qty=1;state.options={};
 const info=groupInfo[category],items=menuItems.filter(x=>x.category===category),lang=languageCopy[currentLanguage]||languageCopy.fr;
 const groupTitles={"Plats":currentLanguage==="ar"?"الأطباق والتخصصات":currentLanguage==="en"?"Platters & specialities":info.title,"Tajines":currentLanguage==="ar"?"الطواجن":info.title,"Pizzas":currentLanguage==="ar"?"البيتزا":info.title,"Pâtes & gratins":currentLanguage==="ar"?"المعكرونة والغراتان":currentLanguage==="en"?"Pasta & gratins":info.title,"Boissons":currentLanguage==="ar"?"المشروبات":currentLanguage==="en"?"Drinks":info.title,"Fritures":currentLanguage==="ar"?"المقليات":currentLanguage==="en"?"Fried seafood":info.title,"Grillades":currentLanguage==="ar"?"المشويات":currentLanguage==="en"?"Grilled seafood":info.title,"Salades":currentLanguage==="ar"?"السلطات":currentLanguage==="en"?"Salads":info.title,"Jus":currentLanguage==="ar"?"العصائر":currentLanguage==="en"?"Juices":info.title};
 const groupSubs={"Plats":currentLanguage==="ar"?"أطباق بحرية سخية للمشاركة":currentLanguage==="en"?"Generous seafood dishes to share":info.sub,"Tajines":currentLanguage==="ar"?"نكهات المطبخ المغربي":currentLanguage==="en"?"Flavours of Moroccan cuisine":info.sub,"Pizzas":currentLanguage==="ar"?"اختر البيتزا والحجم المناسب":currentLanguage==="en"?"Choose your recipe and size":info.sub,"Pâtes & gratins":currentLanguage==="ar"?"وصفات بحرية وكلاسيكية شهية":currentLanguage==="en"?"Favourite seafood and classic recipes":info.sub,"Boissons":currentLanguage==="ar"?"أكمل وجبتك بمشروب منعش":currentLanguage==="en"?"Complete your meal":info.sub,"Fritures":currentLanguage==="ar"?"أطباق بحرية مقلية":currentLanguage==="en"?"Fried seafood":info.sub,"Grillades":currentLanguage==="ar"?"أسماك ومأكولات بحرية مشوية":currentLanguage==="en"?"Grilled seafood":info.sub,"Salades":currentLanguage==="ar"?"سلطات طازجة":currentLanguage==="en"?"Fresh salads":info.sub,"Jus":currentLanguage==="ar"?"عصائر وفواكه طازجة":currentLanguage==="en"?"Fresh juices and fruit":info.sub};
 $("#modalTitle").textContent=groupTitles[category]||({Fritures:currentLanguage==="ar"?"المقليات":currentLanguage==="en"?"Fried seafood":info.title,Grillades:currentLanguage==="ar"?"المشويات":currentLanguage==="en"?"Grilled seafood":info.title,Salades:currentLanguage==="ar"?"السلطات":currentLanguage==="en"?"Salads":info.title,Jus:currentLanguage==="ar"?"العصائر":currentLanguage==="en"?"Juices":info.title})[category]||info.title||category;
 $("#modalDescription").textContent=groupSubs[category]||info.sub||"";
 $("#modalImage").style.backgroundImage=`url("${info.image}")`;
 $("#modalPrice").textContent=lang.selectDish;
 let html=`<div class="option-group"><span class="option-title">${lang.choose}</span><div class="option-list dish-choices">${items.map((item,i)=>`<button type="button" class="option-pill dish-choice ${i===0?"active":""}" data-item="${item.id}">${translateItem(item).name} · ${item.largePrice?`${money(item.price)} / ${money(item.largePrice)}`:money(item.price)}</button>`).join("")}</div></div>`;
 if(category==="Pizzas"||category==="Boissons")html+=`<div class="option-group"><span class="option-title">${lang.size}</span><div class="option-list"><button type="button" class="option-pill size-choice active" data-size="M">${category==="Boissons"?(currentLanguage==="ar"?"صغيرة":currentLanguage==="en"?"Small":"Petite") : lang.medium}</button><button type="button" class="option-pill size-choice" data-size="G">${category==="Boissons"?(currentLanguage==="ar"?"كبيرة":currentLanguage==="en"?"Large":"Grande") : lang.large}</button></div></div>`;
 if(category!=="Boissons"&&category!=="Jus")html+=`<div class="option-group"><span class="option-title">${lang.preference}</span><div class="option-list"><button type="button" class="option-pill preference-choice active" data-preference="Standard">${lang.standard}</button><button type="button" class="option-pill preference-choice" data-preference="Sans piment">${lang.noSpicy}</button></div></div>`;
 $("#optionsWrap").innerHTML=html;
 state.options={size:"M",preference:"Standard"};
 $("#qtyValue").textContent="1";updateModalTotal();
 $("#dishModal").classList.add("open");$("#dishModal").setAttribute("aria-hidden","false");document.body.style.overflow="hidden";
}
function updateModalTotal(){
 if(!state.selectedItem)return;
 const hasSize=Boolean(state.selectedItem.largePrice)&&(state.activeCategory==="Pizzas"||state.activeCategory==="Boissons");
 const unit=hasSize&&state.options.size==="G"?state.selectedItem.largePrice:state.selectedItem.price;
 $("#modalPrice").textContent=money(unit);
 $("#qtyValue").textContent=state.qty;
 $("#modalTotal").textContent=money(unit*state.qty);
}
function closeModal(){$("#dishModal").classList.remove("open");$("#dishModal").setAttribute("aria-hidden","true");document.body.style.overflow="";}
function renderCart(){const count=state.cart.reduce((n,x)=>n+x.qty,0),total=state.cart.reduce((n,x)=>n+x.qty*x.price,0);$("#cartCount").textContent=count;$("#cartTotal").textContent=money(total);const lang=typeof languageCopy!=="undefined"?(languageCopy[currentLanguage]||languageCopy.fr):null;const label=$("#cartDock .cart-summary strong");if(label)label.innerHTML=`<span id="cartCount">${count}</span> ${lang?lang.items:"article(s)"}`;$("#cartDock").classList.toggle("visible",count>0)}
document.addEventListener("click",e=>{
 const card=e.target.closest(".group-card");if(card){openCategory(card.dataset.category);return;}
 const chip=e.target.closest(".category-chip");if(chip){state.category=chip.dataset.category;document.querySelectorAll(".category-chip").forEach(c=>c.classList.toggle("selected",c===chip));renderMenu();return;}
 const dish=e.target.closest(".dish-choice");if(dish){state.selectedItem=menuItems.find(x=>x.id===dish.dataset.item);document.querySelectorAll(".dish-choice").forEach(b=>b.classList.toggle("active",b===dish));$("#modalDescription").textContent=translateItem(state.selectedItem).desc;updateModalTotal();return;}
 const size=e.target.closest(".size-choice");if(size){state.options.size=size.dataset.size;document.querySelectorAll(".size-choice").forEach(b=>b.classList.toggle("active",b===size));updateModalTotal();return;}
 const pref=e.target.closest(".preference-choice");if(pref){state.options.preference=pref.dataset.preference;document.querySelectorAll(".preference-choice").forEach(b=>b.classList.toggle("active",b===pref));return;}
});
$("#menuSearch").addEventListener("input",e=>{state.search=e.target.value;renderMenu()});
$("#modalClose").addEventListener("click",closeModal);
$("#dishModal").addEventListener("click",e=>{if(e.target===$("#dishModal"))closeModal()});
document.addEventListener("keydown",e=>{if(e.key==="Escape")closeModal();if((e.key==="Enter"||e.key===" ")&&e.target.matches(".food-card"))openCategory(e.target.dataset.category)});
$("#qtyMinus").addEventListener("click",()=>{state.qty=Math.max(1,state.qty-1);updateModalTotal()});
$("#qtyPlus").addEventListener("click",()=>{state.qty=Math.min(30,state.qty+1);updateModalTotal()});
$("#addToOrder").addEventListener("click",()=>{
 if(!state.selectedItem)return;
 const hasSize=Boolean(state.selectedItem.largePrice)&&(state.activeCategory==="Pizzas"||state.activeCategory==="Boissons");
 const size=hasSize?`${state.activeCategory==="Boissons"?(state.options.size==="G"?(currentLanguage==="ar"?"حجم كبير":currentLanguage==="en"?"Large":"Grande"):(currentLanguage==="ar"?"حجم صغير":currentLanguage==="en"?"Small":"Petite")):`Taille ${state.options.size==="G"?"Grande":"Moyenne"}`}`:"";
 const preference=state.options.preference&&state.options.preference!=="Standard"?state.options.preference:"";
 const options=[size,preference].filter(Boolean).join(", ");
 const price=hasSize&&state.options.size==="G"?state.selectedItem.largePrice:state.selectedItem.price;
 state.cart.push({id:state.selectedItem.id,name:translateItem(state.selectedItem).name,price,qty:state.qty,options});
 closeModal();renderCart();
});
$("#checkoutBtn").addEventListener("click",()=>{
 if(!state.cart.length)return;
 const total=state.cart.reduce((n,x)=>n+x.qty*x.price,0);
 const lines=state.cart.map((x,i)=>`${i+1}. ${x.name} x${x.qty} — ${money(x.price*x.qty)}${x.options?`\n   ${x.options}`:""}`);
 const lang=languageCopy[currentLanguage]||languageCopy.fr;const message=`${lang.orderMsg}\n\n${lines.join("\n")}\n\n${lang.total} : ${money(total)}\n\n${lang.name} : \n${lang.delivery} : \n${lang.mode}\n${lang.thanks}`;
 window.open(`https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(message)}`,"_blank","noopener");
});
$("#menuToggle").addEventListener("click",()=>{const nav=$("#mainNav"),open=nav.classList.toggle("open");$("#menuToggle").setAttribute("aria-expanded",String(open))});
$("#mainNav").querySelectorAll("a").forEach(a=>a.addEventListener("click",()=>{$("#mainNav").classList.remove("open");$("#menuToggle").setAttribute("aria-expanded","false")}));
$("#year").textContent=new Date().getFullYear();
