const baseItemText=Object.fromEntries(menuItems.map(x=>[x.id,{name:x.name,desc:x.desc}]));
let currentLanguage='fr';
function translateItem(item){const t=translatedItems[currentLanguage]?.[item.id];return t?{name:t[0],desc:t[1]}:baseItemText[item.id]}
function setText(selector,value){const el=document.querySelector(selector);if(el&&value!==undefined)el.textContent=value}
function applyLanguage(lang){
 currentLanguage=languageCopy[lang]?lang:'fr';const t=languageCopy[currentLanguage];document.documentElement.lang=currentLanguage;document.documentElement.dir=currentLanguage==='ar'?'rtl':'ltr';
 document.querySelectorAll('#mainNav a').forEach((a,i)=>a.textContent=t.nav[i]||a.textContent);
 setText('.announcement',t.announcement+' • Casablanca');setText('.header-order',t.order+' ↗');
 const eyebrow=document.querySelector('.eyebrow');if(eyebrow)eyebrow.innerHTML='<span></span> '+t.eyebrow;
 const h1=document.querySelector('.hero h1');if(h1)h1.innerHTML=t.heroTitle;setText('.hero-content>p',t.heroText);
 const heroButtons=document.querySelectorAll('.hero-actions a');if(heroButtons[0])heroButtons[0].innerHTML=t.explore+' <span>↗</span>';if(heroButtons[1])heroButtons[1].innerHTML=t.find+' <span>↗</span>';
 setText('.hero-proof small',t.rating);const proofSmalls=document.querySelectorAll('.hero-proof small');if(proofSmalls[1])proofSmalls[1].textContent=t.budget;
 setText('.categories .section-kicker',t.kicker);const categoryH=document.querySelector('.categories h2');if(categoryH)categoryH.innerHTML=t.categoryTitle;setText('.categories .section-heading-row p',t.categoryText);
 const chips=document.querySelectorAll('.category-chip');if(chips[0])chips[0].innerHTML='<span>✦</span> '+t.all;chips.forEach((c,i)=>{if(i>0&&t.filter[i-1])c.innerHTML='<span>'+c.querySelector('span').textContent+'</span> '+t.filter[i-1]});
 setText('.menu-intro .section-kicker',t.favorites);const mh=document.querySelector('.menu-intro h2');if(mh)mh.innerHTML=t.menuTitle;const search=document.querySelector('#menuSearch');if(search){search.placeholder=t.search;search.setAttribute('aria-label',t.search)}setText('.menu-footnote',t.footnote);
 setText('.gallery-section .section-kicker',t.gallery);const gh=document.querySelector('.gallery-section h2');if(gh)gh.innerHTML=t.galleryTitle;setText('.gallery-section .section-heading-row p',t.galleryText);const insta=document.querySelector('.gallery-section .under-link');if(insta)insta.innerHTML=t.instagram+' <span>↗</span>';
 setText('.feature-content .section-kicker',t.story);const fh=document.querySelector('.feature-content h2');if(fh)fh.innerHTML=t.storyTitle;setText('.feature-content p',t.storyText);const visit=document.querySelector('.feature-content .btn');if(visit)visit.innerHTML=t.visit+' <span>↗</span>';
 setText('.contact-section .section-kicker',t.contactKicker);const ch=document.querySelector('.contact-section h2');if(ch)ch.innerHTML=t.contactTitle;setText('.contact-section>div:first-child p',t.contactText);
 const contactLabels=document.querySelectorAll('.contact-item small');[t.address,t.phone,t.hours].forEach((v,i)=>{if(contactLabels[i])contactLabels[i].textContent=v});const contactLinks=document.querySelectorAll('.contact-item a');if(contactLinks[0])contactLinks[0].textContent=t.directions;if(contactLinks[1])contactLinks[1].textContent=t.call;const hourStrong=document.querySelector('.contact-item:nth-child(3) strong');if(hourStrong)hourStrong.textContent=t.hoursValue;setText('.contact-item .muted',t.hoursNote);const follow=document.querySelector('.contact-card>.btn');if(follow)follow.innerHTML=t.follow+' <span>↗</span>';setText('.footer>a:last-child',t.back);
 const modalKicker=document.querySelector('.modal-content .section-kicker');if(modalKicker)modalKicker.textContent=t.modalKicker;setText('.modal-price-row span',t.unitPrice);setText('.quantity-row>span',t.quantity);setText('.modal-total span',t.total);const add=$('#addToOrder');if(add)add.innerHTML=t.add+' <span>＋</span>';const checkout=$('#checkoutBtn');if(checkout)checkout.innerHTML=t.checkout+' <span>↗</span>';const empty=document.querySelector('.empty-state');if(empty)empty.textContent=t.empty;
 renderMenu();if(state.activeCategory&&$('#dishModal').classList.contains('open'))openCategory(state.activeCategory);renderCart();
}
$('#languageSelect').addEventListener('change',e=>applyLanguage(e.target.value));
const root=document.documentElement;const themeButton=$('#themeToggle');function setTheme(theme){root.dataset.theme=theme;const dark=theme==='dark';themeButton.querySelector('.theme-icon').textContent=dark?'☀':'☾';themeButton.setAttribute('aria-label',dark?'Activer le thème clair':'Activer le thème sombre');themeButton.title=dark?'Thème clair':'Thème sombre'}
setTheme('light');themeButton.addEventListener('click',()=>setTheme(root.dataset.theme==='dark'?'light':'dark'));
try{const savedTheme=localStorage.getItem('ali-theme');if(savedTheme==='dark'||savedTheme==='light')setTheme(savedTheme);themeButton.addEventListener('click',()=>localStorage.setItem('ali-theme',root.dataset.theme));const savedLang=localStorage.getItem('ali-language');if(savedLang&&languageCopy[savedLang])$('#languageSelect').value=savedLang;}catch(e){}
// Staggered reveal animations, while respecting reduced-motion preferences.
if('IntersectionObserver'in window&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');revealObserver.unobserve(entry.target)}}),{threshold:.12});document.querySelectorAll('.categories,.menu-section,.gallery-section,.feature-band,.contact-section,.food-card,.gallery-item').forEach((el,i)=>{el.classList.add('reveal');el.style.transitionDelay=`${Math.min(i%5,4)*70}ms`;revealObserver.observe(el)});}

// Official menu page viewer
(()=>{const viewer=document.getElementById('menuPageLightbox');const image=document.getElementById('menuPageLargeImage');const closeButton=document.getElementById('menuPageClose');if(!viewer||!image||!closeButton)return;document.querySelectorAll('[data-menu-page]').forEach(button=>button.addEventListener('click',()=>{image.src=button.dataset.menuPage;image.alt=button.querySelector('img')?.alt||'Menu page';viewer.classList.add('open');viewer.setAttribute('aria-hidden','false');document.body.style.overflow='hidden'}));const close=()=>{viewer.classList.remove('open');viewer.setAttribute('aria-hidden','true');image.src='';document.body.style.overflow=''};closeButton.addEventListener('click',close);viewer.addEventListener('click',event=>{if(event.target===viewer)close()});document.addEventListener('keydown',event=>{if(event.key==='Escape')close()})})();
try{applyLanguage($('#languageSelect').value||'fr');}catch(error){console.error('Language initialization failed',error);renderMenu();}
$('#languageSelect').addEventListener('change',e=>{try{localStorage.setItem('ali-language',e.target.value)}catch(error){} });
